// --- I. CORE PREPROCESSOR UTILITIES (No Change) ---

// Forces expansion of A and B before pasting (crucial for macro arguments).
#define PP_PASTE_IMPL(A, B) A##B
#define PP_PASTE(A, B) PP_PASTE_IMPL(A, B)

// Used for argument counting and dispatch (Max 5 for module name, Max 4 for members).
#define GET_MEMBER_COUNT(_1, _2, _3, _4, _5, COUNT, ...) COUNT


// --- III. VARIADIC MEMBER INITIALIZER GENERATION ---

// Helper macro to generate a single member declaration: typeof(*NAME.MEMBER) NAME_MEMBER;
#define __MODULE_DEFINE_DECLARE_ONE(NAME, MEMBER) \
    typeof(*NAME.MEMBER) PP_PASTE(NAME, PP_PASTE(_, MEMBER));

// Fixed-arity macros to generate the declarations (no commas needed)
#define __MODULE_DEFINE_DECLARE_4(NAME, M1, M2, M3, M4) \
    __MODULE_DEFINE_DECLARE_3(NAME, M1, M2, M3) \
    __MODULE_DEFINE_DECLARE_ONE(NAME, M4)

#define __MODULE_DEFINE_DECLARE_3(NAME, M1, M2, M3) \
    __MODULE_DEFINE_DECLARE_2(NAME, M1, M2) \
    __MODULE_DEFINE_DECLARE_ONE(NAME, M3)

#define __MODULE_DEFINE_DECLARE_2(NAME, M1, M2) \
    __MODULE_DEFINE_DECLARE_ONE(NAME, M1) \
    __MODULE_DEFINE_DECLARE_ONE(NAME, M2)

#define __MODULE_DEFINE_DECLARE_1(NAME, M1) \
    __MODULE_DEFINE_DECLARE_ONE(NAME, M1)

// Helper macro to generate a single member initialization: .MEMBER = NAME_MEMBER
#define __MODULE_DEFINE_INIT_ONE(NAME, MEMBER) \
    .MEMBER = PP_PASTE(NAME, PP_PASTE(_, MEMBER))

// Fixed-arity macros to generate the comma-separated initializer list.
#define __MODULE_DEFINE_INIT_4(NAME, M1, M2, M3, M4) \
    __MODULE_DEFINE_INIT_3(NAME, M1, M2, M3), __MODULE_DEFINE_INIT_ONE(NAME, M4)

#define __MODULE_DEFINE_INIT_3(NAME, M1, M2, M3) \
    __MODULE_DEFINE_INIT_2(NAME, M1, M2), __MODULE_DEFINE_INIT_ONE(NAME, M3)

#define __MODULE_DEFINE_INIT_2(NAME, M1, M2) \
    __MODULE_DEFINE_INIT_1(NAME, M1), __MODULE_DEFINE_INIT_ONE(NAME, M2)

#define __MODULE_DEFINE_INIT_1(NAME, M1) \
    __MODULE_DEFINE_INIT_ONE(NAME, M1)


// --- IV. __MODULE_DEFINE (The Final Macro) ---

/**
 * Creates a module instance definition with variadic members, including 
 * forward declarations using typeof() for the implementation functions.
 * Arguments: (ModuleNameConcatenated, Member1, Member2, ...)
 */

#define __FUNCS_DECL(NAME, ...)	\
    extern const PP_PASTE(NAME, _Interface) NAME; \
    PP_PASTE(__MODULE_DEFINE_DECLARE_, \
        GET_MEMBER_COUNT(0, __VA_ARGS__, 4, 3, 2, 1)) (NAME, __VA_ARGS__) \

#define __MODULE_DEFINE(NAME, ...) \
    /* 3. Actual Definition: Defines the module instance using the declared functions. */ \
    typeof(__PATH_CAT_NAME(module)) NAME = { \
        PP_PASTE(__MODULE_DEFINE_INIT_, \
            GET_MEMBER_COUNT(0, __VA_ARGS__, 4, 3, 2, 1)) \
        (NAME, __VA_ARGS__) \
    }






















